import { render } from '@solidjs/web';
import { lazy, Loading } from 'solid-js';

import Greeting from './greeting';

function App() {
  return (
    <>
      <h1>Welcome</h1>
      <Loading fallback={<p>Loading greeting...</p>}>
        <Greeting name="Jake" />
      </Loading>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

